    fn address_set(values: &[u64]) -> Set<u64> {
        Set(values.iter().copied().collect())
    }

    fn seed_pointer_width_copy(
        prog: &mut RTLPassProgram,
        node: u64,
        src_name: &'static str,
        dst_name: &'static str,
    ) {
        let src_sym: &'static str =
            Box::leak(format!("pointer_copy_src_{node:x}").into_boxed_str());
        let dst_sym: &'static str =
            Box::leak(format!("pointer_copy_dst_{node:x}").into_boxed_str());
        prog.instruction
            .push((node, 3, "", "MOV", src_sym, dst_sym, "", "", 0, 0));
        prog.op_register
            .extend([(src_sym, src_name), (dst_sym, dst_name)]);
    }

    #[derive(Clone, Copy)]
    struct DirectPointerFixture {
        func: u64,
        entry_block: u64,
        header_block: u64,
        exit_block: u64,
        base_def: u64,
        endpoint_def: u64,
        step: u64,
        access: u64,
        latch: u64,
        exit: u64,
    }

    fn seed_direct_pointer_fixture(
        prog: &mut RTLPassProgram,
        start: i64,
        end: i64,
        delta: i64,
        access_displacement: i64,
        frame_size: u64,
    ) -> DirectPointerFixture {
        seed_direct_pointer_fixture_with(
            prog,
            start,
            end,
            delta,
            frame_size,
            Operation::Oaddlimm(delta),
            Some(LTLInst::Lstore(
                MemoryChunk::MInt8Unsigned,
                Addressing::Aindexed(access_displacement),
                Arc::new(vec![Mreg::AX]),
                Mreg::SI,
            )),
            true,
        )
    }

    fn seed_direct_pointer_fixture_with(
        prog: &mut RTLPassProgram,
        start: i64,
        end: i64,
        delta: i64,
        frame_size: u64,
        step_operation: Operation,
        access_inst: Option<LTLInst>,
        access_after_step: bool,
    ) -> DirectPointerFixture {
        seed_direct_pointer_fixture_with_raw_step(
            prog,
            start,
            end,
            delta,
            frame_size,
            step_operation,
            access_inst,
            access_after_step,
            "ADD",
        )
    }

    fn seed_direct_pointer_fixture_with_raw_step(
        prog: &mut RTLPassProgram,
        start: i64,
        end: i64,
        delta: i64,
        frame_size: u64,
        step_operation: Operation,
        access_inst: Option<LTLInst>,
        access_after_step: bool,
        raw_step_mnemonic: &'static str,
    ) -> DirectPointerFixture {
        // Deliberately unrelated numeric order: every ordering/reachability
        // fact below is structural.
        let fixture = DirectPointerFixture {
            func: 0x1000,
            entry_block: 0x9000,
            header_block: 0x3000,
            exit_block: 0x5000,
            base_def: 0x8800,
            endpoint_def: 0x8600,
            step: 0x2300,
            access: 0x2200,
            latch: 0x2100,
            exit: 0x200,
        };
        let header = 0x2400;
        let physical_jcc = 0x2050;

        for block in [
            fixture.entry_block,
            fixture.header_block,
            fixture.exit_block,
        ] {
            prog.block_in_function.push((block, fixture.func));
            prog.instr_in_function.push((block, fixture.func));
        }
        for (node, block) in [
            (fixture.func, fixture.entry_block),
            (fixture.base_def, fixture.entry_block),
            (fixture.endpoint_def, fixture.entry_block),
            (header, fixture.header_block),
            (fixture.step, fixture.header_block),
            (fixture.access, fixture.header_block),
            (fixture.latch, fixture.header_block),
            (physical_jcc, fixture.header_block),
            (fixture.exit, fixture.exit_block),
        ] {
            prog.code_in_block.push((node, block));
            prog.instr_in_function.push((node, fixture.func));
        }
        prog.asm_block_next.extend([
            (fixture.entry_block, fixture.header_block),
            (fixture.header_block, fixture.header_block),
            (fixture.header_block, fixture.exit_block),
        ]);
        prog.settled_block_dom_set.extend([
            (
                fixture.func,
                fixture.entry_block,
                address_set(&[fixture.entry_block]),
            ),
            (
                fixture.func,
                fixture.header_block,
                address_set(&[fixture.entry_block, fixture.header_block]),
            ),
            (
                fixture.func,
                fixture.exit_block,
                address_set(&[
                    fixture.entry_block,
                    fixture.header_block,
                    fixture.exit_block,
                ]),
            ),
        ]);
        prog.rtl_next
            .extend([(fixture.latch, header), (fixture.latch, fixture.exit)]);
        prog.ddisasm_cfg_edge.push((physical_jcc, header, "branch"));
        prog.abi_pointer_size.push((8,));
        prog.exact_frame_stack_lea.extend([
            (fixture.func, fixture.base_def, start),
            (fixture.func, fixture.endpoint_def, end),
        ]);
        prog.instruction.push((
            fixture.step,
            4,
            "",
            raw_step_mnemonic,
            "direct_pointer_step_imm",
            "direct_pointer_step_dst",
            "",
            "",
            0,
            0,
        ));
        prog.op_immediate
            .push(("direct_pointer_step_imm", delta, 8));
        prog.op_register.push(("direct_pointer_step_dst", "RAX"));
        prog.function_has_ltl_body.push((fixture.func,));
        prog.func_stacksz.push((
            fixture.func,
            fixture.exit,
            "direct_pointer_fixture",
            frame_size,
        ));

        prog.ltl_inst.extend([
            (
                fixture.base_def,
                LTLInst::Lop(
                    Operation::Oleal(Addressing::Ainstack(start)),
                    Arc::new(vec![]),
                    Mreg::AX,
                ),
            ),
            (
                fixture.endpoint_def,
                LTLInst::Lop(
                    Operation::Oleal(Addressing::Ainstack(end)),
                    Arc::new(vec![]),
                    Mreg::CX,
                ),
            ),
            (
                fixture.step,
                LTLInst::Lop(step_operation, Arc::new(vec![Mreg::AX]), Mreg::AX),
            ),
            (
                fixture.latch,
                LTLInst::Lcond(
                    Condition::Ccomplu(Comparison::Cne),
                    Arc::new(vec![Mreg::AX, Mreg::CX]),
                    Either::Right(header),
                    Either::Right(fixture.exit),
                ),
            ),
        ]);
        let has_access = access_inst.is_some();
        if let Some(access_inst) = access_inst {
            prog.ltl_inst.push((fixture.access, access_inst));
        }
        prog.reg_def.extend([
            (fixture.base_def, Mreg::AX),
            (fixture.endpoint_def, Mreg::CX),
            (fixture.step, Mreg::AX),
        ]);
        prog.reg_def_used.extend([
            (fixture.base_def, Mreg::AX, fixture.step),
            (fixture.step, Mreg::AX, fixture.latch),
            (fixture.endpoint_def, Mreg::CX, fixture.latch),
        ]);
        if has_access {
            prog.reg_def_used
                .push((fixture.step, Mreg::AX, fixture.access));
        }
        prog.block_last_def
            .push((fixture.latch, fixture.step, Mreg::AX));
        if has_access && access_after_step {
            prog.block_last_def
                .push((fixture.access, fixture.step, Mreg::AX));
        }
        fixture
    }

    #[test]
    fn direct_pointer_contract_rejects_cross_stride_access_and_wrong_latch_direction() {
        assert!(direct_pointer_after_step_access_fits_stride(
            1,
            -1,
            &MemoryChunk::MInt8Unsigned,
        ));
        assert!(!direct_pointer_after_step_access_fits_stride(
            1,
            0,
            &MemoryChunk::MInt8Unsigned,
        ));
        assert!(direct_pointer_after_step_access_fits_stride(
            -1,
            0,
            &MemoryChunk::MInt8Unsigned,
        ));
        assert!(!direct_pointer_after_step_access_fits_stride(
            -1,
            -1,
            &MemoryChunk::MInt8Unsigned,
        ));

        assert!(direct_pointer_interval_within_local_frame(0, 32, 40));
        assert!(direct_pointer_interval_within_local_frame(-40, 0, 40));
        assert!(!direct_pointer_interval_within_local_frame(40, 48, 40));
        assert!(!direct_pointer_interval_within_local_frame(-8, 8, 40));

        let ne = Condition::Ccomplu(Comparison::Cne);
        assert!(direct_pointer_loop_continues_toward_endpoint(
            &ne, false, true, 1, 8,
        ));
        assert!(!direct_pointer_loop_continues_toward_endpoint(
            &Condition::Ccomplu(Comparison::Cle),
            false,
            true,
            1,
            8,
        ));
        // `endpoint > induction` is the rhs-normalized form of
        // `induction < endpoint` and is valid for a positive step.
        assert!(direct_pointer_loop_continues_toward_endpoint(
            &Condition::Ccomplu(Comparison::Cgt),
            true,
            true,
            1,
            8,
        ));
        assert!(!direct_pointer_loop_continues_toward_endpoint(
            &Condition::Ccompu(Comparison::Cne),
            false,
            true,
            1,
            8,
        ));
    }

    #[test]
    fn direct_pointer_walk_proves_preincrement_phase_reverse_phase_and_local_frame() {
        on_large_stack(|| {
            let mut forward = RTLPassProgram::default();
            let fixture = seed_direct_pointer_fixture(&mut forward, 0, 32, 1, -1, 40);
            forward.run();
            assert!(forward
                .stack_pointer_walk_region
                .iter()
                .any(|fact| fact == &(fixture.func, 0, 32)));
            drop(forward);

            // `use p[0]; ++p` is not the gcc preincrement witness. The seeded
            // def-use can be loop-carried, but no same-iteration last-def fact
            // proves the access follows this step.
            let mut postincrement = RTLPassProgram::default();
            let _fixture = seed_direct_pointer_fixture_with(
                &mut postincrement,
                0,
                32,
                1,
                40,
                Operation::Oaddlimm(1),
                Some(LTLInst::Lstore(
                    MemoryChunk::MInt8Unsigned,
                    Addressing::Aindexed(0),
                    Arc::new(vec![Mreg::AX]),
                    Mreg::SI,
                )),
                false,
            );
            postincrement.run();
            assert!(postincrement.stack_pointer_walk_region.is_empty());
            drop(postincrement);

            let mut narrow_step = RTLPassProgram::default();
            let _fixture = seed_direct_pointer_fixture_with(
                &mut narrow_step,
                0,
                32,
                1,
                40,
                Operation::Oaddimm(1),
                Some(LTLInst::Lstore(
                    MemoryChunk::MInt8Unsigned,
                    Addressing::Aindexed(-1),
                    Arc::new(vec![Mreg::AX]),
                    Mreg::SI,
                )),
                true,
            );
            narrow_step.run();
            assert!(narrow_step.stack_pointer_walk_region.is_empty());
            drop(narrow_step);

            // Superset lifting represents carry-dependent ADC/SBB fallbacks
            // as an Oaddlimm candidate too. Their raw mnemonic is therefore a
            // mandatory part of the fixed-step proof.
            for mnemonic in ["ADC", "SBB"] {
                let mut carry_step = RTLPassProgram::default();
                seed_direct_pointer_fixture_with_raw_step(
                    &mut carry_step,
                    0,
                    32,
                    1,
                    40,
                    Operation::Oaddlimm(1),
                    Some(LTLInst::Lstore(
                        MemoryChunk::MInt8Unsigned,
                        Addressing::Aindexed(-1),
                        Arc::new(vec![Mreg::AX]),
                        Mreg::SI,
                    )),
                    true,
                    mnemonic,
                );
                carry_step.run();
                assert!(
                    carry_step.stack_pointer_walk_region.is_empty(),
                    "{mnemonic} must not become a constant pointer recurrence"
                );
            }

            let mut reverse = RTLPassProgram::default();
            let fixture = seed_direct_pointer_fixture(&mut reverse, 32, 0, -1, 0, 40);
            reverse.run();
            assert!(reverse
                .stack_pointer_walk_region
                .iter()
                .any(|fact| fact == &(fixture.func, 0, 32)));
            drop(reverse);

            // These coordinates are above the recovered local frame and name
            // incoming/caller storage despite having a valid loop shape.
            let mut incoming = RTLPassProgram::default();
            seed_direct_pointer_fixture(&mut incoming, 40, 48, 1, -1, 40);
            incoming.run();
            assert!(incoming.stack_pointer_walk_region.is_empty());
        });
    }

    #[test]
    fn direct_pointer_walk_requires_decoded_width_local_frame_endpoints() {
        on_large_stack(|| {
            // The LTL superset can retain a 64-bit alternative for a decoded
            // 32-bit LEA.  Neither endpoint is a machine pointer on LP64, so
            // the otherwise-valid loop contract must not publish an object.
            let mut narrow = RTLPassProgram::default();
            let fixture = seed_direct_pointer_fixture(&mut narrow, 0, 32, 1, -1, 40);
            for (node, dst_sym, dst_name, src_sym, ofs) in [
                (
                    fixture.base_def,
                    "narrow_base_dst",
                    "EAX",
                    "narrow_base_src",
                    0_i64,
                ),
                (
                    fixture.endpoint_def,
                    "narrow_end_dst",
                    "ECX",
                    "narrow_end_src",
                    32_i64,
                ),
            ] {
                narrow.plea.push((node, dst_sym, src_sym));
                narrow.op_register.push((dst_sym, dst_name));
                narrow
                    .op_indirect
                    .push((src_sym, "", "RSP", "NONE", 1, ofs, 8));
            }
            narrow.run();
            assert!(narrow.stack_pointer_walk_region.is_empty());
            drop(narrow);

            // Pointer-width LEAs above an established frame pointer name the
            // caller's incoming area, not this callee's local frame.  The
            // numeric interval happens to fit the recovered frame size, so
            // only exact local-frame provenance can reject this false walk.
            let mut incoming = RTLPassProgram::default();
            let fixture = seed_direct_pointer_fixture(&mut incoming, 16, 32, 1, -1, 40);
            let frame_setup = 0x20f8;
            incoming.instr_in_function.push((frame_setup, fixture.func));
            incoming.stack_base_move.push((frame_setup, "RSP", "RBP"));
            incoming.abi_incoming_bp_stack_base.push((16,));
            for (node, dst_sym, dst_name, src_sym, ofs) in [
                (
                    fixture.base_def,
                    "incoming_base_dst",
                    "RAX",
                    "incoming_base_src",
                    16_i64,
                ),
                (
                    fixture.endpoint_def,
                    "incoming_end_dst",
                    "RCX",
                    "incoming_end_src",
                    32_i64,
                ),
            ] {
                incoming.plea.push((node, dst_sym, src_sym));
                incoming.op_register.push((dst_sym, dst_name));
                incoming
                    .op_indirect
                    .push((src_sym, "", "RBP", "NONE", 1, ofs, 8));
            }
            incoming.run();
            assert!(incoming
                .incoming_stack_tail_base
                .iter()
                .any(|(_, node, _, _)| *node == fixture.base_def));
            assert!(incoming.stack_pointer_walk_region.is_empty());
        });
    }

    #[test]
    fn direct_pointer_walk_requires_a_closed_linear_body() {
        on_large_stack(|| {
            for incomplete_kind in 0..3 {
                let mut prog = RTLPassProgram::default();
                let fixture = seed_direct_pointer_fixture(&mut prog, 0, 32, 1, -1, 40);
                match incomplete_kind {
                    0 => prog.function_has_uncovered_block.push((fixture.func,)),
                    1 => prog
                        .function_unknown_terminal
                        .push((fixture.func, fixture.exit)),
                    2 => prog
                        .function_unresolved_control
                        .push((fixture.func, fixture.latch)),
                    _ => unreachable!(),
                };

                prog.run();
                assert!(
                    prog.stack_pointer_walk_region.is_empty(),
                    "incomplete Linear body kind {incomplete_kind} must veto an otherwise valid walk"
                );
            }
        });
    }

    #[test]
    fn direct_pointer_walk_rejects_loop_local_reset_and_late_multihop_ambiguity() {
        on_large_stack(|| {
            let mut reset = RTLPassProgram::default();
            let fixture = seed_direct_pointer_fixture(&mut reset, 0, 32, 1, -1, 40);
            let reset_def = 0x20f0;
            reset.instr_in_function.push((reset_def, fixture.func));
            reset.code_in_block.push((reset_def, fixture.header_block));
            reset.reg_def.push((reset_def, Mreg::AX));
            reset.ltl_inst.push((
                reset_def,
                LTLInst::Lop(Operation::Olongconst(7), Arc::new(vec![]), Mreg::AX),
            ));
            reset.reg_def_used.push((reset_def, Mreg::AX, fixture.step));
            reset.run();
            assert!(reset.stack_pointer_walk_region.is_empty());
            drop(reset);

            // A trimmed raw write is still an architectural kill.  It has no
            // effective value definition for the ordinary reaching-def set,
            // but must not let the older frame pointer appear to reach the
            // recurrence unchanged inside the same block.
            let mut trimmed_reset = RTLPassProgram::default();
            let fixture = seed_direct_pointer_fixture(&mut trimmed_reset, 0, 32, 1, -1, 40);
            let trimmed_def = 0x20e8;
            trimmed_reset
                .instr_in_function
                .push((trimmed_def, fixture.func));
            trimmed_reset
                .code_in_block
                .push((trimmed_def, fixture.header_block));
            trimmed_reset.reg_def.push((trimmed_def, Mreg::AX));
            trimmed_reset.trim_instruction.push((trimmed_def,));
            trimmed_reset.next.push((trimmed_def, fixture.step));
            trimmed_reset.run();
            assert!(trimmed_reset.stack_pointer_walk_region.is_empty());
            drop(trimmed_reset);

            // At a join, one known stack-address arm plus one decoder-visible
            // trimmed kill is not a MUST initial value.  Exercise the
            // point-keyed unknown-state lattice across two CFG edges rather
            // than manually injecting its derived summary.
            let mut trimmed_join = RTLPassProgram::default();
            let fixture = seed_direct_pointer_fixture(&mut trimmed_join, 0, 32, 1, -1, 40);
            let unknown_block = 0x7400;
            let unknown_def = 0x7410;
            trimmed_join
                .block_in_function
                .push((unknown_block, fixture.func));
            trimmed_join
                .instr_in_function
                .extend([(unknown_block, fixture.func), (unknown_def, fixture.func)]);
            trimmed_join
                .code_in_block
                .push((unknown_def, unknown_block));
            trimmed_join
                .block_last_insn
                .push((unknown_block, unknown_def));
            trimmed_join.asm_block_next.extend([
                (fixture.entry_block, unknown_block),
                (unknown_block, fixture.header_block),
            ]);
            trimmed_join.settled_block_dom_set.push((
                fixture.func,
                unknown_block,
                address_set(&[fixture.entry_block, unknown_block]),
            ));
            trimmed_join.reg_def.push((unknown_def, Mreg::AX));
            trimmed_join.trim_instruction.push((unknown_def,));
            trimmed_join.run();
            assert!(trimmed_join.stack_pointer_walk_region.is_empty());
            drop(trimmed_join);

            let mut ambiguous = RTLPassProgram::default();
            let fixture = seed_direct_pointer_fixture(&mut ambiguous, 0, 32, 1, -1, 40);
            let value_def = 0x8a10;
            let first_copy = 0x8a20;
            let second_copy = 0x8a30;
            for node in [value_def, first_copy, second_copy] {
                ambiguous.instr_in_function.push((node, fixture.func));
                ambiguous.code_in_block.push((node, fixture.entry_block));
            }
            ambiguous.ltl_inst.extend([
                (
                    value_def,
                    LTLInst::Lop(Operation::Olongconst(5), Arc::new(vec![]), Mreg::AX),
                ),
                (
                    first_copy,
                    LTLInst::Lop(Operation::Omove, Arc::new(vec![Mreg::AX]), Mreg::R15),
                ),
                (
                    second_copy,
                    LTLInst::Lop(Operation::Omove, Arc::new(vec![Mreg::R15]), Mreg::AX),
                ),
            ]);
            ambiguous.reg_def.extend([
                (value_def, Mreg::AX),
                (first_copy, Mreg::R15),
                (second_copy, Mreg::AX),
            ]);
            ambiguous.reg_def_used.extend([
                (fixture.base_def, Mreg::AX, first_copy),
                (value_def, Mreg::AX, first_copy),
                (first_copy, Mreg::R15, second_copy),
                (second_copy, Mreg::AX, fixture.step),
            ]);
            seed_pointer_width_copy(&mut ambiguous, first_copy, "RAX", "R15");
            seed_pointer_width_copy(&mut ambiguous, second_copy, "R15", "RAX");
            ambiguous.run();
            assert!(ambiguous.stack_pointer_walk_region.is_empty());
        });
    }

    #[test]
    fn direct_pointer_walk_closes_derived_hidden_and_escape_uses() {
        on_large_stack(|| {
            // A pointer-width-truncating value computation is an allowed leaf,
            // not pointer provenance on LP64.
            let mut narrowing = RTLPassProgram::default();
            let fixture = seed_direct_pointer_fixture(&mut narrowing, 0, 32, 1, -1, 40);
            let value_use = 0x20e0;
            narrowing.instr_in_function.push((value_use, fixture.func));
            narrowing
                .code_in_block
                .push((value_use, fixture.header_block));
            narrowing.ltl_inst.push((
                value_use,
                LTLInst::Lop(
                    Operation::Olea(Addressing::Aindexed2(0)),
                    Arc::new(vec![Mreg::R8, Mreg::AX]),
                    Mreg::SI,
                ),
            ));
            narrowing
                .reg_def_used
                .push((fixture.step, Mreg::AX, value_use));
            // The raw decoder also describes LEA with an indirect operand.
            // It computes an address but does not observe memory, so this must
            // not become a hidden-memory veto merely because AX is the base.
            narrowing.unrefinedinstruction.push((
                value_use,
                3,
                "",
                "LEA",
                "narrowing_mem",
                "",
                "",
                "",
                0,
                0,
            ));
            narrowing
                .op_indirect
                .push(("narrowing_mem", "", "RAX", "NONE", 1, 0, 4));
            narrowing.reg_use.push((value_use, Mreg::AX));
            narrowing
                .block_last_def
                .push((value_use, fixture.step, Mreg::AX));
            narrowing.run();
            assert!(narrowing
                .stack_pointer_walk_region
                .iter()
                .any(|fact| fact == &(fixture.func, 0, 32)));
            drop(narrowing);

            // A pointer copy remains provenance, but a range-checked access
            // through that exact copied definition is a supported observer.
            let mut copied = RTLPassProgram::default();
            let fixture = seed_direct_pointer_fixture_with(
                &mut copied,
                0,
                32,
                1,
                40,
                Operation::Oaddlimm(1),
                None,
                false,
            );
            let copy = 0x20d8;
            copied.instr_in_function.push((copy, fixture.func));
            copied.code_in_block.push((copy, fixture.header_block));
            copied.ltl_inst.extend([
                (
                    copy,
                    LTLInst::Lop(Operation::Omove, Arc::new(vec![Mreg::AX]), Mreg::R8),
                ),
                (
                    fixture.access,
                    LTLInst::Lstore(
                        MemoryChunk::MInt8Unsigned,
                        Addressing::Aindexed(-1),
                        Arc::new(vec![Mreg::R8]),
                        Mreg::SI,
                    ),
                ),
            ]);
            copied.reg_def.push((copy, Mreg::R8));
            copied.reg_def_used.extend([
                (fixture.step, Mreg::AX, copy),
                (copy, Mreg::R8, fixture.access),
            ]);
            copied.block_last_def.extend([
                (copy, fixture.step, Mreg::AX),
                (fixture.access, copy, Mreg::R8),
            ]);
            seed_pointer_width_copy(&mut copied, copy, "RAX", "R8");
            copied.run();
            assert!(copied
                .stack_pointer_walk_region
                .iter()
                .any(|fact| fact == &(fixture.func, 0, 32)));
            drop(copied);

            // A fused/no-LTL semantic memory operation is accepted when its
            // exact carried base and full access width remain in one stride.
            // The raw memory observer at the same site is then explained by
            // that semantic fact instead of vetoing a valid loop.
            let mut fused_in_range = RTLPassProgram::default();
            let fixture = seed_direct_pointer_fixture_with(
                &mut fused_in_range,
                0,
                32,
                4,
                40,
                Operation::Oaddlimm(4),
                None,
                false,
            );
            fused_in_range.float_load_op.push((
                fixture.access,
                Operation::Oaddfs,
                MemoryChunk::MFloat32,
                Addressing::Aindexed(-4),
                Arc::new(vec![Mreg::AX]),
                Mreg::X0,
                false,
            ));
            fused_in_range.unrefinedinstruction.push((
                fixture.access,
                4,
                "",
                "ADDSS",
                "fused_in_range_mem",
                "XMM0",
                "",
                "",
                0,
                0,
            ));
            fused_in_range
                .op_indirect
                .push(("fused_in_range_mem", "", "RAX", "NONE", 1, -4, 4));
            fused_in_range.reg_use.push((fixture.access, Mreg::AX));
            fused_in_range
                .block_last_def
                .push((fixture.access, fixture.step, Mreg::AX));
            fused_in_range.run();
            assert!(fused_in_range
                .stack_pointer_walk_region
                .iter()
                .any(|fact| fact == &(fixture.func, 0, 32)));
            drop(fused_in_range);

            // Trimmed sites are absent from global reg_def_used. Capstone's
            // universal reg_use must still close pure-register MOV/arithmetic
            // consumers, or their hidden result can kill and launder the
            // carried pointer before a later escape.
            for (index, mnemonic) in ["MOV", "ADD"].into_iter().enumerate() {
                let mut trimmed = RTLPassProgram::default();
                let fixture = seed_direct_pointer_fixture(&mut trimmed, 0, 32, 1, -1, 40);
                let hidden = 0x20f0 + index as u64;
                let src_operand = if mnemonic == "MOV" {
                    "trimmed_mov_src"
                } else {
                    "trimmed_add_src"
                };
                let dst_operand = if mnemonic == "MOV" {
                    "trimmed_mov_dst"
                } else {
                    "trimmed_add_dst"
                };
                trimmed.instr_in_function.push((hidden, fixture.func));
                trimmed.code_in_block.push((hidden, fixture.header_block));
                trimmed.unrefinedinstruction.push((
                    hidden,
                    3,
                    "",
                    mnemonic,
                    dst_operand,
                    src_operand,
                    "",
                    "",
                    0,
                    0,
                ));
                trimmed.op_register.push((src_operand, "RAX"));
                trimmed.op_register.push((dst_operand, "R8"));
                trimmed.reg_use.push((hidden, Mreg::AX));
                trimmed.reg_def.push((hidden, Mreg::R8));
                trimmed.trim_instruction.push((hidden,));
                trimmed
                    .block_last_def
                    .push((hidden, fixture.step, Mreg::AX));
                trimmed.run();
                assert!(
                    trimmed.stack_pointer_walk_region.is_empty(),
                    "trimmed {mnemonic} must remain a closed-use veto"
                );
            }

            // A generic trimmed instruction has no surviving Mach/LTL value
            // definition in production: asm_pass removes it before lifting.
            // Retaining the Lop in this fixture exercises a deliberately
            // inconsistent superset state, and the decoder-visible trimmed
            // write must remain an unknown recurrence value rather than being
            // exempted merely because the stale Lop resembles the step.
            let mut trimmed_step = RTLPassProgram::default();
            let fixture = seed_direct_pointer_fixture(&mut trimmed_step, 0, 32, 1, -1, 40);
            trimmed_step.trim_instruction.push((fixture.step,));
            trimmed_step.reg_use.push((fixture.step, Mreg::AX));
            trimmed_step.run();
            assert!(trimmed_step.stack_pointer_walk_region.is_empty());
            drop(trimmed_step);

            // Multi-hop copies remain pointer-capable; an eventual dynamic
            // dereference outside the admitted direct-use shape vetoes it.
            let mut derived = RTLPassProgram::default();
            let fixture = seed_direct_pointer_fixture(&mut derived, 0, 32, 1, -1, 40);
            let copy1 = 0x20d0;
            let copy2 = 0x20c0;
            let hidden_load = 0x20b0;
            for node in [copy1, copy2, hidden_load] {
                derived.instr_in_function.push((node, fixture.func));
                derived.code_in_block.push((node, fixture.header_block));
            }
            derived.ltl_inst.extend([
                (
                    copy1,
                    LTLInst::Lop(Operation::Omove, Arc::new(vec![Mreg::AX]), Mreg::R8),
                ),
                (
                    copy2,
                    LTLInst::Lop(Operation::Omove, Arc::new(vec![Mreg::R8]), Mreg::R9),
                ),
                (
                    hidden_load,
                    LTLInst::Lload(
                        MemoryChunk::MInt8Unsigned,
                        Addressing::Aindexed(7),
                        Arc::new(vec![Mreg::R9]),
                        Mreg::DX,
                    ),
                ),
            ]);
            derived.reg_def_used.extend([
                (fixture.step, Mreg::AX, copy1),
                (copy1, Mreg::R8, copy2),
                (copy2, Mreg::R9, hidden_load),
            ]);
            derived
                .reg_def
                .extend([(copy1, Mreg::R8), (copy2, Mreg::R9)]);
            derived.block_last_def.extend([
                (copy1, fixture.step, Mreg::AX),
                (copy2, copy1, Mreg::R8),
                (hidden_load, copy2, Mreg::R9),
            ]);
            seed_pointer_width_copy(&mut derived, copy1, "RAX", "R8");
            seed_pointer_width_copy(&mut derived, copy2, "R8", "R9");
            derived.run();
            assert!(derived.stack_pointer_walk_region.is_empty());
            drop(derived);

            // The use is trimmed/no-LTL, so only the raw operand plus the
            // point-keyed reaching-def contract can expose it.
            let mut fused = RTLPassProgram::default();
            let fixture = seed_direct_pointer_fixture(&mut fused, 0, 32, 1, -1, 40);
            let hidden = 0x20a0;
            fused.instr_in_function.push((hidden, fixture.func));
            fused.code_in_block.push((hidden, fixture.header_block));
            fused
                .unrefinedinstruction
                .push((hidden, 3, "", "ADD", "hidden_mem", "", "", "", 0, 0));
            fused
                .op_indirect
                .push(("hidden_mem", "", "RAX", "NONE", 1, 7, 1));
            fused.reg_use.push((hidden, Mreg::AX));
            fused.trim_instruction.push((hidden,));
            fused.block_last_def.push((hidden, fixture.step, Mreg::AX));
            fused.run();
            assert!(fused.stack_pointer_walk_region.is_empty());
            drop(fused);

            // A semantic in-range store cannot mask the same carried value
            // escaping as its source operand.
            let mut store_value = RTLPassProgram::default();
            let _fixture = seed_direct_pointer_fixture_with(
                &mut store_value,
                0,
                32,
                1,
                40,
                Operation::Oaddlimm(1),
                Some(LTLInst::Lstore(
                    MemoryChunk::MInt8Unsigned,
                    Addressing::Aindexed(-1),
                    Arc::new(vec![Mreg::AX]),
                    Mreg::AX,
                )),
                true,
            );
            store_value.run();
            assert!(store_value.stack_pointer_walk_region.is_empty());
            drop(store_value);

            // The raw decoder has the same role distinction: AX is both the
            // admitted address base and a separate stored value operand.
            let mut raw_store_value = RTLPassProgram::default();
            let fixture = seed_direct_pointer_fixture(&mut raw_store_value, 0, 32, 1, -1, 40);
            raw_store_value.unrefinedinstruction.push((
                fixture.access,
                3,
                "",
                "MOV",
                "raw_store_mem",
                "raw_store_src",
                "",
                "",
                0,
                0,
            ));
            raw_store_value
                .op_indirect
                .push(("raw_store_mem", "", "RAX", "NONE", 1, -1, 1));
            raw_store_value.op_register.push(("raw_store_src", "RAX"));
            raw_store_value.reg_use.push((fixture.access, Mreg::AX));
            raw_store_value.run();
            assert!(raw_store_value.stack_pointer_walk_region.is_empty());
            drop(raw_store_value);

            for escape_kind in 0..5 {
                let mut escaped = RTLPassProgram::default();
                let fixture = seed_direct_pointer_fixture(&mut escaped, 0, 32, 1, -1, 40);
                let observer = 0x2090 + escape_kind;
                escaped.instr_in_function.push((observer, fixture.func));
                escaped.code_in_block.push((observer, fixture.exit_block));
                match escape_kind {
                    0 => {
                        escaped.ltl_inst.push((
                            observer,
                            LTLInst::Lsetstack(Mreg::AX, Slot::Local, 8, Typ::Tany64),
                        ));
                        escaped
                            .reg_def_used
                            .push((fixture.step, Mreg::AX, observer));
                    }
                    1 => {
                        escaped.ltl_inst.push((
                            observer,
                            LTLInst::Lcall(Either::Right(Either::Right("sink"))),
                        ));
                        escaped
                            .arg_setup_candidate
                            .push((fixture.step, Mreg::AX, observer));
                    }
                    2 => {
                        escaped.ltl_inst.push((observer, LTLInst::Lreturn));
                        escaped
                            .def_reaches_return
                            .push((observer, fixture.step, Mreg::AX));
                        escaped.abi_ret_int_reg.push((Mreg::AX,));
                    }
                    3 => {
                        // Signature/arity filtering is allowed to omit the
                        // printable argument, but the structural call observer
                        // still closes an exact carried copy in an ABI arg reg.
                        let copy = 0x2080;
                        escaped.instr_in_function.push((copy, fixture.func));
                        escaped.code_in_block.push((copy, fixture.header_block));
                        escaped.ltl_inst.extend([
                            (
                                copy,
                                LTLInst::Lop(Operation::Omove, Arc::new(vec![Mreg::AX]), Mreg::DI),
                            ),
                            (
                                observer,
                                LTLInst::Ltailcall(Either::Right(Either::Right("sink"))),
                            ),
                        ]);
                        escaped.reg_def.push((copy, Mreg::DI));
                        escaped.reg_def_used.push((fixture.step, Mreg::AX, copy));
                        escaped.block_last_def.push((copy, fixture.step, Mreg::AX));
                        escaped.def_reaches_call.push((observer, copy, Mreg::DI));
                        escaped.abi_int_arg_position.push((Mreg::DI, 0));
                        seed_pointer_width_copy(&mut escaped, copy, "RAX", "RDI");
                    }
                    _ => {
                        // Raw PUSH is an implicit value observer and therefore
                        // has its own reaching-def relation instead of a
                        // reg_def_used edge.
                        escaped
                            .push_arg_def
                            .push((observer, Mreg::AX, fixture.step));
                    }
                }
                escaped.run();
                assert!(escaped.stack_pointer_walk_region.is_empty());
            }
        });
    }

    #[test]
    fn direct_pointer_walk_settles_endpoint_and_public_extent_ambiguity() {
        on_large_stack(|| {
            let mut endpoint = RTLPassProgram::default();
            let fixture = seed_direct_pointer_fixture(&mut endpoint, 0, 32, 1, -1, 40);
            let alternate_endpoint = 0x8b00;
            endpoint
                .instr_in_function
                .push((alternate_endpoint, fixture.func));
            endpoint
                .code_in_block
                .push((alternate_endpoint, fixture.entry_block));
            endpoint.reg_def.push((alternate_endpoint, Mreg::CX));
            endpoint.ltl_inst.push((
                alternate_endpoint,
                LTLInst::Lop(
                    Operation::Oleal(Addressing::Ainstack(24)),
                    Arc::new(vec![]),
                    Mreg::CX,
                ),
            ));
            endpoint
                .reg_def_used
                .push((alternate_endpoint, Mreg::CX, fixture.latch));
            endpoint.run();
            assert!(endpoint.stack_pointer_walk_region.is_empty());
            drop(endpoint);

            // Seed the settled-candidate stratum directly to exercise the
            // final ambiguity gate and every eager public side effect.
            let mut conflicting = RTLPassProgram::default();
            conflicting
                .direct_pointer_walk_region_candidate
                .extend([(0x7000, 0, 24), (0x7000, 0, 32)]);
            conflicting.run();
            assert!(conflicting.stack_pointer_walk_region.is_empty());
            assert!(conflicting.escaped_stack_region_caller_field.is_empty());
            assert!(conflicting.escaped_stack_region_extent.is_empty());
        });
    }

    fn seed_materialized_branch(
        prog: &mut RTLPassProgram,
        func: u64,
        source: u64,
        jcc: u64,
        stale: u64,
        taken: u64,
    ) {
        prog.next.push((source, jcc));
        prog.next.push((jcc, stale));
        prog.ltl_inst.push((stale, LTLInst::Lreturn));
        prog.pjcc.push((jcc, TestCond::CondE, "taken"));
        prog.rtl_inst_candidate.push((
            jcc,
            RTLInst::Icond(
                Condition::Ccompimm(Comparison::Ceq, 0),
                Arc::new(vec![0x7777]),
                Either::Right(taken),
                Either::Right(stale),
            ),
        ));
        for node in [source, jcc, stale, taken] {
            prog.instr_in_function.push((node, func));
        }
    }

    fn seed_complete_local_function(
        prog: &mut RTLPassProgram,
        name: &'static str,
        start: u64,
        end: u64,
    ) {
        prog.func_span.push((name, start, end));
        prog.function_has_ltl_body.push((start,));
    }

    #[test]
    fn scheduled_setcc_reads_compare_value_and_defines_at_setcc() {
        on_large_stack(|| {
            let mut prog = RTLPassProgram::default();
            let compare = 0x900;
            let setcc = 0x100;
            let compared_value = 0x5000;
            let boolean_value = fresh_xtl_reg(setcc, Mreg::AX);

            prog.setcc_compare_site.push((setcc, compare));
            prog.ltl_inst.push((
                setcc,
                LTLInst::Lop(
                    Operation::Ocmp(Condition::Ccompimm(Comparison::Ceq, 5)),
                    Arc::new(vec![Mreg::AX]),
                    Mreg::AX,
                ),
            ));
            prog.reg_xtl.push((compare, Mreg::AX, compared_value));

            prog.run();

            assert!(prog.rtl_inst_candidate.iter().any(|(node, inst)| {
                *node == setcc
                    && matches!(
                        inst,
                        RTLInst::Iop(Operation::Ocmp(_), args, dst)
                            if args.as_slice() == [compared_value] && *dst == boolean_value
                    )
            }));
            assert!(!prog.rtl_inst_candidate.iter().any(|(node, inst)| {
                *node == setcc
                    && matches!(
                        inst,
                        RTLInst::Iop(Operation::Ocmp(_), args, _)
                            if args.as_slice() == [boolean_value]
                    )
            }));
        });
    }

    #[test]
    fn stack_setcc_defines_the_reloads_cell_from_the_flags_origin_value() {
        on_large_stack(|| {
            let mut prog = RTLPassProgram::default();
            let func = 0x400;
            let flags_origin = 0x900;
            let setcc = 0x100;
            let reload = 0x700;
            let block = 0x550;
            let compared_value = 0x5000;
            let later_register_value = 0x6000;

            prog.mach_stack_setcc.push((
                setcc,
                50,
                flags_origin,
                Operation::Ocmp(Condition::Ccompimm(Comparison::Cne, 0)),
                Arc::new(vec![Mreg::BX]),
            ));
            // EBX has a different value by the time SETcc executes.  The
            // boolean must still consume the value TEST saw at flags_origin.
            prog.reg_xtl.push((flags_origin, Mreg::BX, compared_value));
            prog.reg_xtl.push((setcc, Mreg::BX, later_register_value));

            prog.stack_def_used
                .push((setcc, "RSP", 50, reload, "RSP", 50));
            prog.ltl_inst.push((
                reload,
                LTLInst::Lgetstack(Slot::Local, 50, Typ::Tint, Mreg::SI),
            ));
            for node in [flags_origin, setcc, reload] {
                prog.instr_in_function.push((node, func));
                prog.code_in_block.push((node, block));
            }
            prog.next.push((setcc, reload));

            prog.run();

            let setcc_cells: BTreeSet<_> = prog
                .stack_var
                .iter()
                .filter_map(|(f, node, ofs, local)| {
                    (*f == func && *node == setcc && *ofs == 50).then_some(*local)
                })
                .collect();
            let reload_cells: BTreeSet<_> = prog
                .stack_var
                .iter()
                .filter_map(|(f, node, ofs, local)| {
                    (*f == func && *node == reload && *ofs == 50).then_some(*local)
                })
                .collect();
            let cell = *setcc_cells
                .intersection(&reload_cells)
                .next()
                .expect("SETcc and its reaching reload must share one frame-cell identity");

            assert!(prog.rtl_inst_candidate.iter().any(|fact| {
                fact == &(
                    setcc,
                    RTLInst::Iop(
                        Operation::Ocmp(Condition::Ccompimm(Comparison::Cne, 0)),
                        Arc::new(vec![compared_value]),
                        cell,
                    ),
                )
            }));
            assert!(!prog.rtl_inst_candidate.iter().any(|(node, inst)| {
                *node == setcc
                    && matches!(inst, RTLInst::Iop(Operation::Ocmp(_), args, _)
                        if args.as_slice() == [later_register_value])
            }));
            assert!(prog.rtl_inst_candidate.iter().any(|(node, inst)| {
                *node == reload
                    && matches!(inst, RTLInst::Iop(Operation::Omove, args, _)
                        if args.as_slice() == [cell])
            }));
            assert!(prog
                .stack_var_chunk
                .iter()
                .any(|fact| fact == &(func, 50, MemoryChunk::MInt8Unsigned)));
            assert!(prog
                .op_produces_bool
                .iter()
                .any(|fact| fact == &(setcc, cell)));
            assert!(prog.synth_only_addr.iter().any(|fact| fact == &(setcc,)));
            assert!(prog
                .rtl_succ_candidate
                .iter()
                .any(|fact| fact == &(setcc, reload)));
        });
    }

    #[test]
    fn stack_setcc_does_not_define_wider_same_offset_reloads() {
        on_large_stack(|| {
            let mut prog = RTLPassProgram::default();
            let func = 0x400;
            let flags_origin = 0x410;
            let explicit_setcc = 0x420;
            let explicit_reload = 0x430;
            let decoded_setcc = 0x440;
            let decoded_reload = 0x450;
            let compared_value = 0x5000;
            let condition = Operation::Ocmp(Condition::Ccompimm(Comparison::Cne, 0));

            for setcc in [explicit_setcc, decoded_setcc] {
                prog.mach_stack_setcc.push((
                    setcc,
                    50,
                    flags_origin,
                    condition.clone(),
                    Arc::new(vec![Mreg::BX]),
                ));
                prog.stack_def_used
                    .push((setcc, "RSP", 50, setcc + 0x10, "RSP", 50));
            }
            prog.reg_xtl.push((flags_origin, Mreg::BX, compared_value));

            // A definite four-byte RTL load must not inherit a one-byte SETcc
            // definition merely because both accesses start at offset 50.
            prog.ltl_inst.push((
                explicit_reload,
                LTLInst::Lload(
                    MemoryChunk::MInt32,
                    Addressing::Ainstack(50),
                    Arc::new(vec![]),
                    Mreg::SI,
                ),
            ));

            // Ordinary direct stack MOVs become Lgetstack(Tint), which loses
            // their byte width.  Retain the decoder's exact dword source width
            // as counterevidence instead of treating Tint as byte-compatible.
            prog.ltl_inst.push((
                decoded_reload,
                LTLInst::Lgetstack(Slot::Local, 50, Typ::Tint, Mreg::DI),
            ));
            prog.pmov
                .push((decoded_reload, "decoded_dst", "decoded_stack_src"));
            prog.op_indirect
                .push(("decoded_stack_src", "", "RSP", "NONE", 1, 50, 4));

            for node in [
                flags_origin,
                explicit_setcc,
                explicit_reload,
                decoded_setcc,
                decoded_reload,
            ] {
                prog.instr_in_function.push((node, func));
            }

            prog.run();

            for setcc in [explicit_setcc, decoded_setcc] {
                assert!(!prog
                    .rtl_inst_candidate
                    .iter()
                    .any(|(node, _)| *node == setcc));
                assert!(!prog.synth_only_addr.iter().any(|fact| fact == &(setcc,)));
                assert!(!prog.op_produces_bool.iter().any(|(node, _)| *node == setcc));
            }
        });
    }

    #[test]
    fn memory_immediate_setcc_uses_normalized_operands_and_flags_origin() {
        on_large_stack(|| {
            let mut prog = RTLPassProgram::default();
            let func = 0x400;
            let compare = 0x900;
            let gap = 0x100;
            let setcc = 0x700;
            let base_value = 0x1234;
            let boolean_value = fresh_xtl_reg(setcc, Mreg::AX);

            // Raw instruction operands are source-first, while pcmp is
            // destination-first: Intel `cmp byte ptr [rax], 0` is therefore
            // (zero, memory) in instruction and (memory, zero) in pcmp.
            prog.instruction
                .push((compare, 3, "", "CMP", "zero", "byte_at_rax", "", "", 0, 0));
            prog.pcmp.push((compare, "byte_at_rax", "zero"));
            prog.op_immediate.push(("zero", 0, 1));
            prog.op_indirect
                .push(("byte_at_rax", "", "RAX", "NONE", 1, 0, 1));
            prog.reg_xtl.push((compare, Mreg::AX, base_value));

            // The SETcc consumes CMP's flags across a scheduled flag-neutral
            // node.  Numeric address order is deliberately unrelated to CFG
            // order; the exported provenance fact is authoritative.
            prog.next.push((compare, gap));
            prog.next.push((gap, setcc));
            prog.setcc_compare_site.push((setcc, compare));
            prog.instruction
                .push((setcc, 3, "", "SETNE", "bool_dst", "0", "0", "0", 0, 0));
            prog.op_register.push(("bool_dst", "AL"));
            prog.reg_xtl.push((setcc, Mreg::AX, boolean_value));
            for node in [compare, gap, setcc] {
                prog.instr_in_function.push((node, func));
            }

            prog.run();

            let loaded = fresh_xtl_reg(compare, Mreg::x86("RTEMP"));
            assert!(prog.rtl_inst_candidate.iter().any(|fact| {
                fact == &(
                    compare,
                    RTLInst::Iload(
                        MemoryChunk::MInt8Unsigned,
                        Addressing::Aindexed(0),
                        Arc::new(vec![base_value]),
                        loaded,
                    ),
                )
            }));
            assert!(prog.rtl_inst_candidate.iter().any(|fact| {
                fact == &(
                    setcc,
                    RTLInst::Iop(
                        Operation::Ocmp(Condition::Ccompimm(Comparison::Cne, 0)),
                        Arc::new(vec![loaded]),
                        boolean_value,
                    ),
                )
            }));
        });
    }

    #[test]
    fn load_overwriting_arg_register_reads_incoming_parameter_value() {
        on_large_stack(|| {
            let mut prog = RTLPassProgram::default();
            let func = 0x1000;
            let node = 0x1010;
            let param_id = fresh_xtl_reg(func, Mreg::DI);
            let shadow_use_id = fresh_xtl_reg(node, Mreg::DI) | (1u64 << 62);

            prog.ltl_inst.push((
                node,
                LTLInst::Lload(
                    MemoryChunk::MAny64,
                    Addressing::Aindexed(0),
                    Arc::new(vec![Mreg::DI]),
                    Mreg::DI,
                ),
            ));
            // Seed the already-proven structural fact under test: DI still
            // holds the caller's value at this load.
            prog.is_arg_reg.push((Mreg::DI,));
            prog.arg_reg_param_live_at.push((func, node, Mreg::DI));
            prog.reg_xtl.push((func, Mreg::DI, param_id));

            prog.run();

            assert!(prog
                .alias_edge
                .iter()
                .any(|fact| fact == &(param_id, shadow_use_id)));
            assert!(prog
                .rtl_inst_candidate
                .iter()
                .any(|(candidate_node, inst)| {
                    *candidate_node == node
                        && matches!(
                            inst,
                            RTLInst::Iload(_, Addressing::Aindexed(0), args, _)
                                if args.as_slice() == [param_id]
                        )
                }));
        });
    }

    #[test]
    fn entry_parameter_spill_ignores_an_unrelated_same_node_definition() {
        on_large_stack(|| {
            let mut prog = RTLPassProgram::default();
            let func = 0x1000;
            let spill = 0x1054;
            let param_id = fresh_xtl_reg(func, Mreg::DI);
            let unrelated_id = fresh_xtl_reg(func, Mreg::DX);
            let stack_id = 0x5000;

            // A function-entry instruction may consume an incoming parameter
            // while defining a different register (for example
            // `movzbl (%rdi), %edx`).  The entry node therefore has a real DX
            // definition alongside DI's synthetic incoming-value definition.
            prog.reg_xtl.push((func, Mreg::DI, param_id));
            prog.reg_xtl.push((func, Mreg::DX, unrelated_id));
            prog.reg_def.push((func, Mreg::DX));
            prog.is_def.push((func, unrelated_id));

            prog.ltl_inst.push((
                spill,
                LTLInst::Lsetstack(Mreg::DI, Slot::Local, 8, Typ::Tany64),
            ));
            prog.instr_in_function.push((spill, func));
            prog.reg_def_used.push((func, Mreg::DI, spill));
            prog.stack_var.push((func, spill, 8, stack_id));

            prog.run();

            assert!(prog
                .asm_effective_def
                .iter()
                .any(|fact| fact == &(func, Mreg::DX)));
            assert!(!prog
                .asm_effective_def
                .iter()
                .any(|fact| fact == &(func, Mreg::DI)));
            assert!(prog
                .def_value_rtl
                .iter()
                .any(|fact| fact == &(func, Mreg::DI, param_id)));
            assert!(prog.rtl_inst_candidate.iter().any(|(node, inst)| {
                *node == spill
                    && matches!(
                        inst,
                        RTLInst::Iop(Operation::Omove, args, dst)
                            if args.as_slice() == [param_id] && *dst == stack_id
                    )
            }));
        });
    }

    #[test]
    fn pushed_stack_arguments_across_cfg_merge_form_one_value_web() {
        on_large_stack(|| {
            let mut prog = RTLPassProgram::default();
            let entry = 0x1000;
            let dispatch = 0x1010;
            let def = 0x2000;
            let push = 0x2010;
            let alternate_def = 0x3000;
            let alternate_push = 0x3010;
            let call = 0x2020;
            let successor = 0x2030;
            let source_rtl = 0x5000;
            let alternate_source_rtl = 0x6000;

            prog.func_span.push(("FUN_1000", entry, successor));
            prog.next.push((entry, dispatch));
            prog.adjusts_stack.push((entry, "RSP", -32));
            prog.jump_table_target.push((dispatch, 0, def));
            // Jump-table recovery publishes the same target as a structural
            // branch edge in the disassembly CFG; stack state follows that
            // ordinary edge rather than a duplicate jump-table-specific rule.
            prog.ddisasm_cfg_edge.push((dispatch, def, "branch"));
            prog.ddisasm_cfg_edge
                .push((dispatch, alternate_def, "fallthrough"));
            prog.next.push((def, push));
            prog.next.push((alternate_def, alternate_push));
            prog.next.push((push, call));
            prog.next.push((call, successor));
            for node in [
                entry,
                dispatch,
                def,
                push,
                alternate_def,
                alternate_push,
                call,
                successor,
            ] {
                prog.instr_in_function.push((node, entry));
            }
            for node in [entry, dispatch] {
                prog.code_in_block.push((node, entry));
            }
            for node in [def, push] {
                prog.code_in_block.push((node, def));
            }
            for node in [alternate_def, alternate_push] {
                prog.code_in_block.push((node, alternate_def));
            }
            for node in [call, successor] {
                prog.code_in_block.push((node, call));
            }
            // The shared register-setup/call tail is a distinct block target.
            // A register PUSH and a stack-memory PUSH cross separate
            // structural predecessors into it.
            prog.ddisasm_cfg_edge.push((push, call, "fallthrough"));
            prog.ddisasm_cfg_edge
                .push((alternate_push, call, "fallthrough"));
            prog.reg_def.push((def, Mreg::CX));
            prog.reg_def.push((alternate_def, Mreg::DX));
            prog.reg_xtl.push((push, Mreg::CX, source_rtl));
            prog.trim_instruction.push((def,));
            prog.trim_instruction.push((alternate_def,));
            prog.instruction
                .push((push, 1, "", "PUSH", "push_src", "", "", "", 0, 0));
            prog.op_register.push(("push_src", "RCX"));
            prog.adjusts_stack.push((push, "RSP", -8));
            prog.instruction.push((
                alternate_push,
                1,
                "",
                "PUSH",
                "stack_push_src",
                "",
                "",
                "",
                0,
                0,
            ));
            prog.op_indirect
                .push(("stack_push_src", "", "RSP", "NONE", 1, 0, 8));
            prog.stack_def_used
                .push((alternate_def, "RSP", 0, alternate_push, "RSP", 0));
            prog.stack_xtl
                .push((entry, alternate_push, 0, alternate_source_rtl));
            prog.adjusts_stack.push((alternate_push, "RSP", -8));
            // RTL consumes only the frame pass's finalized entry coordinates.
            // Both arms push from -32 and join at the call at -40.
            prog.settled_sp_entry_offset.extend([
                (entry, push, -32),
                (entry, alternate_push, -32),
                (entry, call, -40),
            ]);
            prog.ltl_inst.push((
                call,
                LTLInst::Lcall(Either::Right(Either::Right("__fprintf_chk"))),
            ));
            prog.abi_first_stack_arg_position.push((6,));
            prog.abi_outgoing_stack_base.push((0,));
            prog.abi_stack_slot_size.push((8,));

            prog.run();

            let raw_sources: BTreeSet<_> = prog
                .raw_call_outgoing_stack_arg
                .iter()
                .filter_map(|(node, pos, source)| (*node == call && *pos == 6).then_some(*source))
                .collect();
            assert!(raw_sources.is_superset(&BTreeSet::from([source_rtl, alternate_source_rtl])));

            let call_values: Vec<_> = prog
                .call_outgoing_stack_arg
                .iter()
                .filter_map(|(node, pos, value)| (*node == call && *pos == 6).then_some(*value))
                .collect();
            assert_eq!(call_values.len(), 1);
            let call_value = call_values[0];
            for source in [source_rtl, alternate_source_rtl] {
                assert!(prog
                    .xtl_canonical
                    .iter()
                    .any(|fact| fact == &(source, call_value)));
            }
        });
    }

    #[test]
    fn contiguous_entry_pushes_are_frame_setup_not_call_arguments() {
        on_large_stack(|| {
            let mut prog = RTLPassProgram::default();
            let [entry, align, body, end] = synthetic_ids();

            prog.func_stacksz.push((entry, end, "frame_user", 0));
            prog.next.push((entry, align));
            prog.next.push((align, body));
            for node in [entry, align, body] {
                prog.instr_in_function.push((node, entry));
            }
            prog.instruction
                .push((entry, 1, "", "PUSH", "saved", "", "", "", 0, 0));
            prog.instruction
                .push((align, 1, "", "PUSH", "scratch", "", "", "", 0, 0));
            prog.op_register.push(("saved", "RBP"));
            prog.op_register.push(("scratch", "RAX"));
            prog.is_arg_reg.push((Mreg::DI,));

            prog.run();

            assert!(prog
                .prologue_frame_push
                .iter()
                .any(|fact| fact == &(entry,)));
            assert!(prog
                .prologue_frame_push
                .iter()
                .any(|fact| fact == &(align,)));
            assert!(!prog
                .push_arg_reg
                .iter()
                .any(|(node, _)| { *node == entry || *node == align }));
        });
    }

    #[test]
    fn body_register_push_remains_a_stack_argument_candidate() {
        on_large_stack(|| {
            let mut prog = RTLPassProgram::default();
            let [entry, def, push, end] = synthetic_ids();

            prog.func_stacksz.push((entry, end, "caller", 0));
            prog.next.push((entry, def));
            prog.next.push((def, push));
            for node in [entry, def, push] {
                prog.instr_in_function.push((node, entry));
            }
            prog.instruction
                .push((entry, 1, "", "XOR", "", "", "", "", 0, 0));
            prog.instruction
                .push((push, 1, "", "PUSH", "arg", "", "", "", 0, 0));
            prog.op_register.push(("arg", "RAX"));
            prog.is_arg_reg.push((Mreg::DI,));

            prog.run();

            assert!(!prog.prologue_frame_push.iter().any(|fact| fact == &(push,)));
            assert!(prog
                .push_arg_reg
                .iter()
                .any(|fact| fact == &(push, Mreg::AX)));
        });
    }

    #[test]
    fn stack_address_provenance_stops_at_register_redefinition() {
        on_large_stack(|| {
            let [func, block, lea, redefine, copy] = synthetic_ids();
            let mut prog = RTLPassProgram::default();
            prog.abi_pointer_size.push((8,));

            for node in [lea, redefine, copy] {
                prog.instr_in_function.push((node, func));
                prog.code_in_block.push((node, block));
            }
            prog.next.extend([(lea, redefine), (redefine, copy)]);
            prog.reg_def
                .extend([(lea, Mreg::R15), (redefine, Mreg::R15), (copy, Mreg::DI)]);
            prog.reg_use
                .extend([(redefine, Mreg::AX), (copy, Mreg::R15)]);
            prog.ltl_inst.push((
                lea,
                LTLInst::Lop(
                    Operation::Oleal(Addressing::Ainstack(16)),
                    Arc::new(vec![]),
                    Mreg::R15,
                ),
            ));
            prog.ltl_inst.push((
                redefine,
                LTLInst::Lop(Operation::Omove, Arc::new(vec![Mreg::AX]), Mreg::R15),
            ));
            prog.ltl_inst.push((
                copy,
                LTLInst::Lop(Operation::Omove, Arc::new(vec![Mreg::R15]), Mreg::DI),
            ));
            prog.exact_frame_stack_lea.push((func, lea, 16));
            prog.function_has_ltl_body.push((func,));
            seed_pointer_width_copy(&mut prog, redefine, "RAX", "R15");
            seed_pointer_width_copy(&mut prog, copy, "R15", "RDI");

            prog.run();

            assert!(prog
                .reg_def_used
                .iter()
                .any(|fact| fact == &(redefine, Mreg::R15, copy)));
            assert!(!prog
                .reg_def_used
                .iter()
                .any(|fact| fact == &(lea, Mreg::R15, copy)));
            assert!(!prog
                .reg_holds_slot_addr
                .iter()
                .any(|fact| fact == &(func, copy, 16, Mreg::DI)));
        });
    }

    #[test]
    fn pointer_width_stack_lea_drives_exact_outparam_width_chain() {
        on_large_stack(|| {
            let mut prog = RTLPassProgram::default();
            let [caller, lea8, call8, callee8, store8, lea16, call16, callee16, store16, lea64, call64, callee64, store64] =
                synthetic_ids();
            let cases = [
                (
                    lea8,
                    call8,
                    callee8,
                    store8,
                    3_i64,
                    MemoryChunk::MInt8Unsigned,
                ),
                (
                    lea16,
                    call16,
                    callee16,
                    store16,
                    8_i64,
                    MemoryChunk::MInt16Unsigned,
                ),
                (
                    lea64,
                    call64,
                    callee64,
                    store64,
                    16_i64,
                    MemoryChunk::MAny64,
                ),
            ];

            prog.abi_pointer_size.push((8,));
            prog.function_has_ltl_body.push((caller,));
            prog.abi_int_arg_position.push((Mreg::DI, 0));
            for (lea, call, callee, store, ofs, chunk) in cases {
                let param = fresh_xtl_reg(callee, Mreg::DI);
                let value = fresh_xtl_reg(store, Mreg::AX);
                prog.instr_in_function
                    .extend([(lea, caller), (call, caller), (store, callee)]);
                prog.ltl_inst.push((
                    lea,
                    LTLInst::Lop(
                        Operation::Oleal(Addressing::Ainstack(ofs)),
                        Arc::new(vec![]),
                        Mreg::DI,
                    ),
                ));
                prog.exact_frame_stack_lea.push((caller, lea, ofs));
                prog.arg_setup_candidate.push((lea, Mreg::DI, call));
                prog.call_target_func.push((call, callee));
                prog.func_param_validated.push((callee, Mreg::DI));
                prog.reg_rtl.push((callee, Mreg::DI, param));
                prog.rtl_inst_candidate.push((
                    store,
                    RTLInst::Istore(
                        chunk.clone(),
                        Addressing::Aindexed(0),
                        Arc::new(vec![param]),
                        value,
                    ),
                ));
            }

            prog.run();

            for (lea, _, _, _, ofs, chunk) in cases {
                assert!(prog
                    .exact_stack_addr_lea_def
                    .iter()
                    .any(|fact| fact == &(caller, lea, Mreg::DI, ofs, 8)));
                assert!(prog.stack_xtl.iter().any(|(func, node, slot, _)| {
                    *func == caller && *node == lea && *slot == ofs
                }));
                assert!(prog.stack_var.iter().any(|(func, node, slot, _)| {
                    *func == caller && *node == lea && *slot == ofs
                }));
                assert!(prog
                    .reg_holds_slot_addr
                    .iter()
                    .any(|fact| fact == &(caller, lea, ofs, Mreg::DI)));
                assert!(prog
                    .slot_addr_escaped
                    .iter()
                    .any(|fact| fact == &(caller, lea, ofs)));
                assert!(prog
                    .escaped_stack_region_field
                    .iter()
                    .any(|fact| { fact == &(caller, ofs, 0, chunk.clone()) }));
                assert!(prog.rtl_inst_candidate.iter().any(|(node, inst)| {
                    *node == lea
                        && matches!(
                            inst,
                            RTLInst::Iop(
                                Operation::Oleal(Addressing::Ainstack(actual)),
                                args,
                                _
                            ) if *actual == ofs && args.is_empty()
                        )
                }));
            }
        });
    }

    #[test]
    fn exact_stack_lea_identity_has_32_bit_parity_and_rejects_nonpointer_shapes() {
        on_large_stack(|| {
            let [func32, good32, call32, func64, wrong_width, alternate_width, narrow_width, indexed, with_arg, synthetic, frame_setup, incoming, incoming32, incoming32_load] =
                synthetic_ids();

            let mut good = RTLPassProgram::default();
            good.abi_pointer_size.push((4,));
            good.function_has_ltl_body.push((func32,));
            good.instr_in_function.push((good32, func32));
            good.ltl_inst.push((
                good32,
                LTLInst::Lop(
                    Operation::Olea(Addressing::Ainstack(24)),
                    Arc::new(vec![]),
                    Mreg::DI,
                ),
            ));
            good.arg_setup_candidate.push((good32, Mreg::DI, call32));
            good.exact_frame_stack_lea.push((func32, good32, 24));
            good.run();

            assert!(good
                .exact_stack_addr_lea_def
                .iter()
                .any(|fact| fact == &(func32, good32, Mreg::DI, 24, 4)));
            assert!(good
                .stack_xtl
                .iter()
                .any(|(func, node, ofs, _)| { *func == func32 && *node == good32 && *ofs == 24 }));
            assert!(good
                .reg_holds_slot_addr
                .iter()
                .any(|fact| fact == &(func32, good32, 24, Mreg::DI)));
            assert!(good
                .slot_addr_taken_reg
                .iter()
                .any(|(func, node, ofs, _)| { *func == func32 && *node == good32 && *ofs == 24 }));
            assert!(good
                .slot_addr_escaped
                .iter()
                .any(|fact| fact == &(func32, good32, 24)));

            let mut bad = RTLPassProgram::default();
            bad.abi_pointer_size.push((8,));
            bad.function_has_ltl_body.push((func64,));
            for node in [
                wrong_width,
                alternate_width,
                narrow_width,
                indexed,
                with_arg,
                frame_setup,
                incoming,
                incoming32,
                incoming32_load,
            ] {
                bad.instr_in_function.push((node, func64));
            }
            bad.ltl_inst.extend([
                (
                    wrong_width,
                    LTLInst::Lop(
                        Operation::Olea(Addressing::Ainstack(40)),
                        Arc::new(vec![]),
                        Mreg::DI,
                    ),
                ),
                (
                    alternate_width,
                    LTLInst::Lop(
                        Operation::Olea(Addressing::Ainstack(64)),
                        Arc::new(vec![]),
                        Mreg::DI,
                    ),
                ),
                // Superset interpretation: this 64-bit alternative coexists
                // with the decoded EDI operation but is not width authority.
                (
                    alternate_width,
                    LTLInst::Lop(
                        Operation::Oleal(Addressing::Ainstack(64)),
                        Arc::new(vec![]),
                        Mreg::DI,
                    ),
                ),
                // Nor may a same-node superset candidate borrow the raw
                // instruction's absence of decoded width for another Mreg.
                (
                    alternate_width,
                    LTLInst::Lop(
                        Operation::Oleal(Addressing::Ainstack(64)),
                        Arc::new(vec![]),
                        Mreg::SI,
                    ),
                ),
                (
                    narrow_width,
                    LTLInst::Lop(
                        Operation::Olea(Addressing::Ainstack(72)),
                        Arc::new(vec![]),
                        Mreg::DI,
                    ),
                ),
                (
                    indexed,
                    LTLInst::Lop(
                        Operation::Oleal(Addressing::Aindexed(40)),
                        Arc::new(vec![Mreg::SP]),
                        Mreg::SI,
                    ),
                ),
                (
                    with_arg,
                    LTLInst::Lop(
                        Operation::Oleal(Addressing::Ainstack(48)),
                        Arc::new(vec![Mreg::SP]),
                        Mreg::DX,
                    ),
                ),
                (
                    incoming,
                    LTLInst::Lop(
                        Operation::Oleal(Addressing::Ainstack(16)),
                        Arc::new(vec![]),
                        Mreg::AX,
                    ),
                ),
                (
                    incoming32,
                    LTLInst::Lop(
                        Operation::Olea(Addressing::Ainstack(24)),
                        Arc::new(vec![]),
                        Mreg::AX,
                    ),
                ),
                (
                    incoming32_load,
                    LTLInst::Lload(
                        MemoryChunk::MInt32,
                        Addressing::Aindexed(0),
                        Arc::new(vec![Mreg::AX]),
                        Mreg::R8,
                    ),
                ),
            ]);
            bad.arg_setup_candidate
                .push((wrong_width, Mreg::DI, call32));
            bad.indexed_synth_stack_base.push((
                func64,
                synthetic,
                56,
                fresh_xtl_reg(synthetic, Mreg::SP) | FRESH_NS_SP_BASE,
            ));
            bad.abi_incoming_bp_stack_base.push((16,));
            bad.stack_base_move.push((frame_setup, "RSP", "RBP"));
            for (node, dst_sym, dst_name, src_sym, base, ofs) in [
                (alternate_width, "alt_dst", "EDI", "alt_src", "RSP", 64),
                (narrow_width, "narrow_dst", "DI", "narrow_src", "RSP", 72),
                (
                    incoming32,
                    "incoming32_dst",
                    "EAX",
                    "incoming32_src",
                    "RBP",
                    24,
                ),
            ] {
                bad.plea.push((node, dst_sym, src_sym));
                bad.op_register.push((dst_sym, dst_name));
                bad.op_indirect.push((src_sym, "", base, "NONE", 1, ofs, 8));
            }
            bad.plea.push((incoming, "incoming_dst", "incoming_src"));
            bad.op_register.push(("incoming_dst", "RAX"));
            bad.op_indirect
                .push(("incoming_src", "", "RBP", "NONE", 1, 16, 8));
            bad.reg_def_used
                .push((incoming32, Mreg::AX, incoming32_load));
            bad.exact_frame_stack_lea.extend([
                (func64, wrong_width, 40),
                (func64, alternate_width, 64),
                (func64, narrow_width, 72),
                (func64, incoming, 16),
                (func64, incoming32, 24),
            ]);
            bad.run();

            assert!(bad
                .exact_stack_addr_lea_def
                .iter()
                .any(|fact| fact == &(func64, wrong_width, Mreg::DI, 40, 4)));
            assert!(bad
                .decoded_stack_lea_result_width
                .iter()
                .any(|fact| fact == &(alternate_width, Mreg::DI, 4)));
            assert!(bad
                .exact_stack_addr_lea_def
                .iter()
                .any(|fact| fact == &(func64, alternate_width, Mreg::DI, 64, 4)));
            assert!(!bad
                .exact_stack_addr_lea_def
                .iter()
                .any(|(_, node, _, _, width)| *node == alternate_width && *width == 8));
            assert!(!bad
                .op_produces_ptr
                .iter()
                .any(|(node, _)| *node == alternate_width));
            assert!(bad
                .decoded_stack_lea_result_width
                .iter()
                .any(|fact| fact == &(narrow_width, Mreg::DI, 2)));
            assert!(!bad
                .exact_stack_addr_lea_def
                .iter()
                .any(|(_, node, _, _, _)| *node == narrow_width));
            assert!(bad
                .incoming_stack_tail_base
                .iter()
                .any(|fact| fact == &(func64, incoming, 16, Mreg::AX)));
            assert!(bad
                .exact_stack_addr_lea_def
                .iter()
                .any(|fact| fact == &(func64, incoming, Mreg::AX, 16, 8)));
            assert!(!bad
                .exact_local_stack_addr_lea_def
                .iter()
                .any(|(_, node, _, _, _)| *node == incoming));
            assert!(bad
                .op_produces_ptr
                .iter()
                .any(|(node, _)| *node == incoming));
            assert!(!bad
                .incoming_stack_tail_base
                .iter()
                .any(|(_, node, _, _)| *node == incoming32));
            assert!(!bad
                .incoming_stack_tail_load
                .iter()
                .any(|(node, _, _)| *node == incoming32_load));
            assert!(!bad
                .op_produces_ptr
                .iter()
                .any(|(node, _)| *node == incoming32));
            for node in [indexed, with_arg, synthetic] {
                assert!(!bad
                    .exact_stack_addr_lea_def
                    .iter()
                    .any(|(_, candidate, _, _, _)| *candidate == node));
            }
            assert!(!bad
                .stack_xtl
                .iter()
                .any(|(_, node, _, _)| *node == incoming));
            assert!(!bad
                .stack_xtl
                .iter()
                .any(|(_, node, _, _)| *node == wrong_width));
            assert!(!bad
                .reg_holds_slot_addr
                .iter()
                .any(|(_, node, _, _)| *node == wrong_width));
            assert!(!bad
                .slot_addr_taken_reg
                .iter()
                .any(|(_, node, _, _)| *node == wrong_width));
            assert!(!bad
                .slot_addr_taken_reg
                .iter()
                .any(|(_, node, _, _)| *node == alternate_width));
            assert!(!bad
                .slot_addr_escaped
                .iter()
                .any(|(_, node, _)| *node == wrong_width));
            assert!(!bad
                .reg_stack_addr_origins
                .iter()
                .any(|row| row.read().unwrap().1 == synthetic));
            assert!(bad.slot_addr_taken_reg.iter().any(|fact| {
                fact == &(
                    func64,
                    synthetic,
                    56,
                    fresh_xtl_reg(synthetic, Mreg::SP) | FRESH_NS_SP_BASE,
                )
            }));
            assert!(!bad
                .reg_stack_addr_origins
                .iter()
                .any(|row| row.read().unwrap().1 == incoming));
            assert!(!bad
                .slot_addr_taken_reg
                .iter()
                .any(|(_, node, _, _)| *node == incoming));
        });
    }

    #[test]
    fn framed_bp_stack_lea_preserves_result_width_before_identity_normalization() {
        on_large_stack(|| {
            let [func, block, frame_setup, lea64, lea32] = synthetic_ids();
            let mut prog = RTLPassProgram::default();

            prog.abi_pointer_size.push((8,));
            prog.function_has_ltl_body.push((func,));
            prog.block_in_function.push((block, func));
            for node in [frame_setup, lea64, lea32] {
                prog.code_in_block.push((node, block));
                prog.instr_in_function.push((node, func));
            }
            prog.stack_base_move.push((frame_setup, "RSP", "RBP"));
            prog.reg_is_64.extend([("RAX", true), ("EAX", false)]);
            for (node, dst_sym, dst_name, src_sym, ofs) in [
                (lea64, "bp_dst64", "RAX", "bp_src64", -32_i64),
                (lea32, "bp_dst32", "EAX", "bp_src32", -16_i64),
            ] {
                prog.plea.push((node, dst_sym, src_sym));
                prog.op_register.push((dst_sym, dst_name));
                prog.op_indirect
                    .push((src_sym, "", "RBP", "NONE", 1, ofs, 8));
                prog.exact_frame_stack_lea.push((func, node, ofs));
            }

            prog.run();

            for (node, expected, opposite) in [
                (
                    lea64,
                    Operation::Oleal(Addressing::Ainstack(-32)),
                    Operation::Olea(Addressing::Ainstack(-32)),
                ),
                (
                    lea32,
                    Operation::Olea(Addressing::Ainstack(-16)),
                    Operation::Oleal(Addressing::Ainstack(-16)),
                ),
            ] {
                assert!(prog
                    .ltl_inst
                    .iter()
                    .any(|(candidate, inst)| {
                        *candidate == node
                            && matches!(inst, LTLInst::Lop(op, args, _) if *op == expected && args.is_empty())
                    }));
                assert!(!prog.ltl_inst.iter().any(|(candidate, inst)| {
                    *candidate == node && matches!(inst, LTLInst::Lop(op, _, _) if *op == opposite)
                }));
                assert!(prog
                    .rtl_inst_candidate
                    .iter()
                    .any(|(candidate, inst)| {
                        *candidate == node
                            && matches!(inst, RTLInst::Iop(op, args, _) if *op == expected && args.is_empty())
                    }));
                assert!(!prog.rtl_inst_candidate.iter().any(|(candidate, inst)| {
                    *candidate == node && matches!(inst, RTLInst::Iop(op, _, _) if *op == opposite)
                }));
            }

            assert!(prog
                .exact_stack_addr_lea_def
                .iter()
                .any(|fact| fact == &(func, lea64, Mreg::AX, -32, 8)));
            assert!(prog
                .exact_stack_addr_lea_def
                .iter()
                .any(|fact| fact == &(func, lea32, Mreg::AX, -16, 4)));
            assert!(prog.op_produces_ptr.iter().any(|(node, _)| *node == lea64));
            assert!(!prog.op_produces_ptr.iter().any(|(node, _)| *node == lea32));
        });
    }

    #[test]
    fn stack_address_provenance_follows_an_unredefined_copy() {
        on_large_stack(|| {
            let [func, block, lea, copy] = synthetic_ids();
            let mut prog = RTLPassProgram::default();
            prog.abi_pointer_size.push((8,));

            for node in [lea, copy] {
                prog.instr_in_function.push((node, func));
                prog.code_in_block.push((node, block));
            }
            prog.next.push((lea, copy));
            prog.reg_def.extend([(lea, Mreg::R15), (copy, Mreg::DI)]);
            prog.reg_use.push((copy, Mreg::R15));
            prog.ltl_inst.push((
                lea,
                LTLInst::Lop(
                    Operation::Oleal(Addressing::Ainstack(16)),
                    Arc::new(vec![]),
                    Mreg::R15,
                ),
            ));
            prog.ltl_inst.push((
                copy,
                LTLInst::Lop(Operation::Omove, Arc::new(vec![Mreg::R15]), Mreg::DI),
            ));
            prog.exact_frame_stack_lea.push((func, lea, 16));
            prog.function_has_ltl_body.push((func,));
            seed_pointer_width_copy(&mut prog, copy, "R15", "RDI");

            prog.run();

            assert!(prog
                .reg_def_used
                .iter()
                .any(|fact| fact == &(lea, Mreg::R15, copy)));
            assert!(prog
                .reg_holds_slot_addr
                .iter()
                .any(|fact| fact == &(func, copy, 16, Mreg::DI)));
        });
    }

    #[test]
    fn stack_address_provenance_rejects_truncating_register_copies() {
        on_large_stack(|| {
            let [func, block, lea, copy] = synthetic_ids();
            let mut prog = RTLPassProgram::default();
            prog.abi_pointer_size.push((8,));
            for node in [lea, copy] {
                prog.instr_in_function.push((node, func));
                prog.code_in_block.push((node, block));
            }
            prog.next.push((lea, copy));
            prog.reg_def.extend([(lea, Mreg::R15), (copy, Mreg::DI)]);
            prog.reg_use.push((copy, Mreg::R15));
            prog.ltl_inst.extend([
                (
                    lea,
                    LTLInst::Lop(
                        Operation::Oleal(Addressing::Ainstack(16)),
                        Arc::new(vec![]),
                        Mreg::R15,
                    ),
                ),
                (
                    copy,
                    LTLInst::Lop(Operation::Omove, Arc::new(vec![Mreg::R15]), Mreg::DI),
                ),
            ]);
            prog.exact_frame_stack_lea.push((func, lea, 16));
            prog.function_has_ltl_body.push((func,));
            prog.instruction.push((
                copy,
                3,
                "",
                "MOV",
                "truncating_copy_src",
                "truncating_copy_dst",
                "",
                "",
                0,
                0,
            ));
            prog.op_register.extend([
                ("truncating_copy_src", "R15D"),
                ("truncating_copy_dst", "EDI"),
            ]);

            prog.run();

            assert!(!prog
                .pointer_width_reg_copy
                .iter()
                .any(|fact| { fact == &(copy, Mreg::R15, Mreg::DI) }));
            assert!(prog
                .reg_stack_addr_origin_member
                .iter()
                .any(|fact| { fact == &(func, copy, Mreg::DI, StackAddrOrigin::NonStack) }));
            assert!(!prog
                .reg_holds_slot_addr
                .iter()
                .any(|fact| fact == &(func, copy, 16, Mreg::DI)));
        });
    }

    #[test]
    fn stack_address_provenance_rejects_partial_or_truncating_spill_state() {
        on_large_stack(|| {
            for partial_overlap in [false, true] {
                let [func, lea, spill, overwrite, reload] = synthetic_ids();
                let mut prog = RTLPassProgram::default();
                let object_ofs = 32;
                let spill_ofs = 8;
                prog.abi_pointer_size.push((8,));
                prog.function_has_ltl_body.push((func,));
                for node in [lea, spill, overwrite, reload] {
                    prog.instr_in_function.push((node, func));
                }
                prog.ltl_inst.push((
                    lea,
                    LTLInst::Lop(
                        Operation::Oleal(Addressing::Ainstack(object_ofs)),
                        Arc::new(vec![]),
                        Mreg::AX,
                    ),
                ));
                prog.exact_frame_stack_lea.push((func, lea, object_ofs));
                prog.reg_def_used.push((lea, Mreg::AX, spill));

                if partial_overlap {
                    prog.ltl_inst.push((
                        spill,
                        LTLInst::Lsetstack(Mreg::AX, Slot::Local, spill_ofs, Typ::Tany64),
                    ));
                    prog.ltl_inst.push((
                        overwrite,
                        LTLInst::Lsetstack(Mreg::CX, Slot::Local, spill_ofs + 1, Typ::Tint),
                    ));
                    prog.ltl_inst.push((
                        reload,
                        LTLInst::Lgetstack(Slot::Local, spill_ofs, Typ::Tany64, Mreg::DI),
                    ));
                    prog.settled_frame_write_state.push((
                        func,
                        reload,
                        Set(std::collections::BTreeSet::from([
                            FrameWriteOrigin::Write(spill, spill_ofs, 8, spill_ofs, 8),
                            FrameWriteOrigin::Write(overwrite, spill_ofs + 1, 1, spill_ofs, 8),
                        ])),
                    ));
                } else {
                    prog.ltl_inst.push((
                        spill,
                        LTLInst::Lsetstack(Mreg::AX, Slot::Local, spill_ofs, Typ::Tint),
                    ));
                    prog.ltl_inst.push((
                        reload,
                        LTLInst::Lgetstack(Slot::Local, spill_ofs, Typ::Tint, Mreg::DI),
                    ));
                    prog.settled_frame_write_state.push((
                        func,
                        reload,
                        Set::singleton(FrameWriteOrigin::Write(spill, spill_ofs, 4, spill_ofs, 8)),
                    ));
                }
                prog.frame_stack_read_bytes
                    .push((func, reload, spill_ofs, 8));

                prog.run();

                if partial_overlap {
                    assert!(prog
                        .stack_addr_reload_state_conflict
                        .iter()
                        .any(|fact| fact == &(func, reload, Mreg::DI)));
                } else {
                    assert!(prog.stack_addr_reload_edge.is_empty());
                }
                assert!(!prog
                    .reg_holds_slot_addr
                    .iter()
                    .any(|fact| fact == &(func, reload, object_ofs, Mreg::DI)));
            }
        });
    }

    #[test]
