            prog.op_immediate.push(("sentinel", 0x2018, 4));
            prog.pjcc.push((jcc, TestCond::CondNe, "taken"));
            prog.symbol_resolved_addr.push(("taken", taken));
            prog.next.push((cmp, jcc));
